//! The shapes the Jira import sends and accepts. TypeScript bindings are generated by `cargo test`.

use hub_core::{BoardMode, Id, StatusCategory, TypeLevel};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraSettings {
    pub base_url: String,
    /// Set for Jira Cloud (e-mail plus API token); empty for a personal access token.
    pub email: String,
    /// The end of the stored token; none when no token is stored. The token itself is never sent.
    pub token_hint: Option<String>,
    /// True when an address and a token are stored, so imports can run.
    pub configured: bool,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export, optional_fields)]
pub struct JiraSettingsUpdate {
    pub base_url: String,
    pub email: Option<String>,
    /// Blank or absent keeps the stored token.
    pub token: Option<String>,
    pub clear_token: Option<bool>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraTestResult {
    pub ok: bool,
    pub message: String,
    /// `cloud` or `server`, once Jira has answered.
    pub deployment: Option<String>,
    pub version: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraRemoteProject {
    pub key: String,
    pub name: String,
    /// None when Jira would not say.
    pub issue_count: Option<i64>,
    /// A project with this key exists here.
    pub exists: bool,
    /// When it was last imported from Jira, if it ever was.
    pub imported_at: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraTypeMapping {
    pub jira_name: String,
    /// The issue type here; created when the project does not have it.
    pub name: String,
    pub level: TypeLevel,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraStatusMapping {
    pub jira_name: String,
    /// Jira's status category key (`new`, `indeterminate`, `done`); empty when unknown.
    #[serde(default)]
    pub jira_category: String,
    pub name: String,
    pub category: StatusCategory,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraPriorityMapping {
    pub jira_name: String,
    /// 1 is the highest, 5 the lowest.
    pub priority: i64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraUserMapping {
    /// The account id (Cloud) or user key (Server) in Jira.
    pub account: String,
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub email: Option<String>,
    /// The person here; none leaves it to the e-mail address, and then to `createUsers`.
    #[serde(default)]
    pub user_id: Option<Id>,
}

/// How Jira's vocabulary becomes this project's. The preview proposes one; the import takes
/// it back, adjusted. Anything an import meets that is not listed gets the default treatment.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export)]
pub struct JiraMapping {
    pub board_mode: Option<BoardMode>,
    pub types: Vec<JiraTypeMapping>,
    pub statuses: Vec<JiraStatusMapping>,
    pub priorities: Vec<JiraPriorityMapping>,
    pub users: Vec<JiraUserMapping>,
    /// People of Jira without an account here get one: inactive, without a password, so
    /// that their names stay on what they did. Otherwise only their names are kept, as text.
    pub create_users: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraLocalProject {
    pub name: String,
    pub issue_count: i64,
    pub imported_at: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraPreview {
    pub project_key: String,
    pub project_name: String,
    pub issue_count: Option<i64>,
    pub sprints: i64,
    pub versions: i64,
    pub components: i64,
    /// `cloud` or `server`.
    pub deployment: String,
    /// False when Jira's agile API did not answer; sprints then come from the issues themselves.
    pub agile: bool,
    /// The name of the field story points are read from; none when Jira has no such field.
    pub story_points: bool,
    /// The project with this key that already exists here, if any.
    pub local: Option<JiraLocalProject>,
    pub mapping: JiraMapping,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export, optional_fields)]
pub struct JiraImportRequest {
    pub project_key: String,
    /// Allows writing into a project with this key that was not created by an import.
    pub into_existing: Option<bool>,
    /// Lets Jira's version win over issues that were edited here after the last import.
    pub overwrite_local: Option<bool>,
    /// Reads every issue again instead of only those changed in Jira since the last import.
    pub full: Option<bool>,
    pub mapping: Option<JiraMapping>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum JiraJobState {
    Queued,
    Running,
    Done,
    Failed,
    Cancelled,
}

impl JiraJobState {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Queued => "queued",
            Self::Running => "running",
            Self::Done => "done",
            Self::Failed => "failed",
            Self::Cancelled => "cancelled",
        }
    }

    pub fn parse(text: &str) -> Self {
        match text {
            "queued" => Self::Queued,
            "running" => Self::Running,
            "done" => Self::Done,
            "cancelled" => Self::Cancelled,
            _ => Self::Failed,
        }
    }

    pub fn finished(self) -> bool {
        !matches!(self, Self::Queued | Self::Running)
    }
}

/// What a job is doing right now.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum JiraJobStep {
    Waiting,
    Connecting,
    Structure,
    Issues,
    Relations,
    Finished,
}

impl JiraJobStep {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Waiting => "waiting",
            Self::Connecting => "connecting",
            Self::Structure => "structure",
            Self::Issues => "issues",
            Self::Relations => "relations",
            Self::Finished => "finished",
        }
    }

    pub fn parse(text: &str) -> Self {
        match text {
            "connecting" => Self::Connecting,
            "structure" => Self::Structure,
            "issues" => Self::Issues,
            "relations" => Self::Relations,
            "finished" => Self::Finished,
            _ => Self::Waiting,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraNote {
    /// The issue key, or empty when the note is about the import as a whole.
    pub key: String,
    pub reason: String,
}

/// What an import did, kept with the job.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export)]
pub struct JiraReport {
    pub project_created: bool,
    pub created: i64,
    pub updated: i64,
    pub unchanged: i64,
    /// Left as they are: edited here since the last import, or not from Jira at all.
    pub skipped: Vec<JiraNote>,
    pub failed: Vec<JiraNote>,
    pub comments: i64,
    pub worklogs: i64,
    /// History entries written: status, sprint, assignee and estimate changes.
    pub changes: i64,
    pub links: i64,
    pub sprints: i64,
    pub versions: i64,
    pub components: i64,
    pub users_matched: i64,
    /// The names of the people who got an inactive account.
    pub users_created: Vec<String>,
    /// What had no counterpart here and how it was handled.
    pub unmapped: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct JiraJob {
    pub id: Id,
    /// `api` or `csv`.
    pub kind: String,
    pub project_key: String,
    pub state: JiraJobState,
    pub step: JiraJobStep,
    /// How many issues there are to read; none while that is not known.
    pub total: Option<i64>,
    pub processed: i64,
    /// Why the job failed, when it did.
    pub error: Option<String>,
    pub started_by: Option<Id>,
    pub created_at: String,
    pub finished_at: Option<String>,
    pub report: JiraReport,
}

